import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> shopping = new ArrayList<>();
        shopping.add("milk");
        shopping.add("eggs");
        shopping.add("bread");
        shopping.add(1, "apples");
        shopping.set(0, "oat milk");
        shopping.remove("eggs");
        System.out.println(shopping + " has " + shopping.size() + " items");
    }
}
